import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type PiggyBankProps = Record<string, any>;

const PiggyBank: React.FC<PiggyBankProps> = ({
  backgroundColor = "#000000",
  lineColor = "#ffffff",
  coinText = "$",
  transparentBackground = false,
  durationInSeconds = 8,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Calculate number of coins based on duration
  const totalFrames = durationInSeconds * fps;
  const coinInterval = 45;
  const numCoins = Math.max(1, Math.floor((totalFrames - 30) / coinInterval));

  // Calculate the impact/spring scale for each coin dropping
  const scaleSprings = Array.from({ length: numCoins }).map((_, i) => {
    const dropEndFrame = 15 + i * coinInterval + 20;
    return spring({
      frame: frame - dropEndFrame,
      fps,
      config: { damping: 12, stiffness: 120 },
    });
  });

  const totalScaleSum = scaleSprings.reduce((sum, s) => sum + s, 0);
  const sRatio = totalScaleSum / numCoins;

  // Dynamically grow the piggy bank body
  const baseRx = 200;
  const baseRy = 160;
  const maxRx = 280;
  const maxRy = 220;

  const rx = baseRx + (maxRx - baseRx) * sRatio;
  const ry = baseRy + (maxRy - baseRy) * sRatio;

  // Jiggle calculations for organic impact
  const jiggleY = Array.from({ length: numCoins })
    .map((_, i) => {
      const dropEndFrame = 15 + i * coinInterval + 20;
      const p = Math.max(0, frame - dropEndFrame);
      if (p === 0 || p > 20) return 0;
      return Math.sin((p * Math.PI) / 10) * 20 * (1 - p / 20);
    })
    .reduce((a, b) => a + b, 0);

  const jiggleRot = Array.from({ length: numCoins })
    .map((_, i) => {
      const dropEndFrame = 15 + i * coinInterval + 20;
      const p = Math.max(0, frame - dropEndFrame);
      if (p === 0 || p > 20) return 0;
      return Math.sin((p * Math.PI) / 5) * 5 * (1 - p / 20);
    })
    .reduce((a, b) => a + b, 0);

  const breathingScale = Math.sin(frame * 0.05) * 0.02 + 1;

  // Switch to uncomfortable face near the end of the filling process
  const isSad = sRatio > 0.65;

  // Determine if the stress burst lines should appear
  const lastCoinImpactFrame = 15 + (numCoins - 1) * coinInterval + 20;
  const showBurst = frame >= lastCoinImpactFrame;
  const burstSpring = spring({
    frame: frame - lastCoinImpactFrame,
    fps,
    config: { damping: 12, stiffness: 150 },
  });

  const sweatY = Math.sin(frame * 0.2) * 5;

  return (
    <AbsoluteFill
      style={{ backgroundColor: bgColor, transition: "none", fontFamily: "Inter" }}
    >
      <svg width="100%" height="100%" style={{ overflow: "visible" }}>
        {/* Floor Shadow / Ground Line */}
        <ellipse
          cx={width / 2}
          cy={height / 2 + baseRy + 45}
          rx={rx * 0.85}
          ry={25}
          fill="none"
          stroke={lineColor}
          strokeWidth="4"
          strokeDasharray="12 12"
        />

        {/* Pig Group */}
        <g
          transform={`translate(${width / 2}, ${
            height / 2 + baseRy - ry + jiggleY
          }) rotate(${jiggleRot}) scale(${breathingScale})`}
        >
          <defs>
            <clipPath id="slot-clip">
              <rect x="-200" y="-1000" width="400" height={1000 - ry * 0.95 + 4} />
            </clipPath>
          </defs>

          {/* 1. Tail */}
          <path
            d={`M ${-rx} ${-ry * 0.1} C ${-rx - 40} ${-ry * 0.3} ${-rx - 80} ${-ry * 0.1} ${-rx - 60} ${ry * 0.1} C ${-rx - 40} ${ry * 0.3} ${-rx - 20} ${ry * 0.1} ${-rx - 30} ${-ry * 0.1}`}
            stroke={lineColor}
            strokeWidth="8"
            fill="none"
            strokeLinecap="round"
          />

          {/* 2. Back Legs */}
          <rect x={-rx * 0.55} y={ry - 50} width={50} height={80} rx={25} fill={backgroundColor} stroke={lineColor} strokeWidth="8" />
          <rect x={rx * 0.25} y={ry - 50} width={50} height={80} rx={25} fill={backgroundColor} stroke={lineColor} strokeWidth="8" />

          {/* 3. Back Ear */}
          <path
            d={`M ${-rx * 0.05} ${-ry * 0.8} C ${-rx * 0.15} ${-ry * 1.2} ${rx * 0.25} ${-ry * 1.3} ${rx * 0.3} ${-ry * 0.65} Z`}
            fill={backgroundColor}
            stroke={lineColor}
            strokeWidth="8"
            strokeLinejoin="round"
          />

          {/* 4. Main Body */}
          <ellipse cx="0" cy="0" rx={rx} ry={ry} fill={backgroundColor} stroke={lineColor} strokeWidth="8" />

          {/* 5. Front Legs */}
          <rect x={-rx * 0.35} y={ry - 40} width={55} height={85} rx={27.5} fill={backgroundColor} stroke={lineColor} strokeWidth="8" />
          <rect x={rx * 0.45} y={ry - 40} width={55} height={85} rx={27.5} fill={backgroundColor} stroke={lineColor} strokeWidth="8" />

          {/* 6. Front Ear */}
          <path
            d={`M ${rx * 0.2} ${-ry * 0.75} C ${rx * 0.2} ${-ry * 1.2} ${rx * 0.5} ${-ry * 1.2} ${rx * 0.5} ${-ry * 0.6} Z`}
            fill={backgroundColor}
            stroke={lineColor}
            strokeWidth="8"
            strokeLinejoin="round"
          />

          {/* 7. Snout */}
          <g transform={`translate(${rx * 0.95}, ${ry * 0.1})`}>
            <ellipse cx="0" cy="0" rx={45} ry={65} fill={backgroundColor} stroke={lineColor} strokeWidth="8" />
            <ellipse cx="12" cy="-20" rx="8" ry="14" fill="none" stroke={lineColor} strokeWidth="4" />
            <ellipse cx="12" cy="20" rx="8" ry="14" fill="none" stroke={lineColor} strokeWidth="4" />
            <path d="M 25 -10 Q 35 0 25 10" stroke={lineColor} strokeWidth="4" fill="none" strokeLinecap="round" />
          </g>

          {/* 8. Eye & Cheeks */}
          <g transform={`translate(${rx * 0.5}, ${-ry * 0.2})`}>
            {isSad ? (
              <g>
                {/* Scared Eye */}
                <circle cx="0" cy="0" r="15" fill={backgroundColor} stroke={lineColor} strokeWidth="6" />
                <circle cx="0" cy="0" r="5" fill={lineColor} />
              </g>
            ) : (
              <g>
                {/* Happy Eye */}
                <circle cx="0" cy="0" r="15" fill={backgroundColor} stroke={lineColor} strokeWidth="6" />
                <circle cx="5" cy="-5" r="4" fill={lineColor} />
              </g>
            )}
          </g>

          {/* Bandage (when sad) */}
          {isSad && (
            <g transform={`translate(${-rx * 0.2}, ${ry * 0.2}) rotate(-15)`}>
              <rect x="-30" y="-10" width="60" height="20" fill={backgroundColor} stroke={lineColor} strokeWidth="4" rx="5" />
              <rect x="-10" y="-10" width="20" height="20" fill={backgroundColor} stroke={lineColor} strokeWidth="4" rx="2" />
            </g>
          )}

          {/* Sweat drop (when sad) */}
          {isSad && (
            <g transform={`translate(${rx * 0.3}, ${-ry * 0.45 + sweatY})`}>
              <path d="M 0 -15 C 10 0 10 15 0 15 C -10 15 -10 0 0 -15 Z" fill={backgroundColor} stroke={lineColor} strokeWidth="4" strokeLinejoin="round" />
            </g>
          )}

          {/* 9. Slot Base (Dark Hole) */}
          <ellipse cx="0" cy={-ry * 0.95} rx="45" ry="12" fill={backgroundColor} stroke={lineColor} strokeWidth="8" />

          {/* 10. Coins mapped with drop logic */}
          <g clipPath="url(#slot-clip)">
            {Array.from({ length: numCoins }).map((_, i) => {
              const dropStartFrame = 15 + i * coinInterval;
              const dropEndFrame = dropStartFrame + 20;

              const coinY = interpolate(
                frame,
                [dropStartFrame, dropEndFrame],
                [-800, -ry * 0.95 + 4],
                {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: Easing.in(Easing.poly(2)),
                }
              );

              const opacity = interpolate(
                frame,
                [dropEndFrame - 2, dropEndFrame + 5],
                [1, 0],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );

              const showSpeedLines = frame >= dropStartFrame + 5 && frame <= dropEndFrame - 2;

              return (
                <g key={i} transform={`translate(0, ${coinY})`} style={{ opacity }}>
                  {showSpeedLines && (
                    <g stroke={lineColor} strokeWidth="4" strokeLinecap="round">
                      <line x1="-20" y1="-50" x2="-20" y2="-90" />
                      <line x1="20" y1="-40" x2="20" y2="-80" />
                      <line x1="0" y1="-60" x2="0" y2="-110" />
                    </g>
                  )}
                  {/* Coin Thickness */}
                  <circle cx="0" cy="-4" r="35" fill={backgroundColor} stroke={lineColor} strokeWidth="6" />
                  {/* Coin Face */}
                  <circle cx="0" cy="0" r="35" fill={backgroundColor} stroke={lineColor} strokeWidth="6" />
                  {/* Inner Ring */}
                  <circle cx="0" cy="0" r="26" stroke={lineColor} strokeWidth="3" fill="none" strokeDasharray="6 6" />
                  <text
                    x="0"
                    y="2"
                    dominantBaseline="central"
                    fill={lineColor}
                    fontSize="32"
                    textAnchor="middle"
                    fontWeight="900"
                  >
                    {coinText}
                  </text>
                </g>
              );
            })}
          </g>

          {/* 11. Front Lip of Slot */}
          <path
            d={`M -45 ${-ry * 0.95} A 45 12 0 0 0 45 ${-ry * 0.95}`}
            stroke={lineColor}
            strokeWidth="8"
            fill="none"
          />

          {/* 12. Stress Burst Effect */}
          {showBurst && (
            <g transform={`translate(${rx * 0.7}, ${-ry * 0.7}) scale(${burstSpring})`}>
              <path
                d="M -20 -10 L -30 -30 M 0 -15 L 0 -40 M 20 -10 L 30 -30"
                stroke={lineColor}
                strokeWidth="6"
                strokeLinecap="round"
              />
            </g>
          )}
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default PiggyBank;